const files=JSON.parse(gunzipSync(Buffer.from(encoded,'base64')).toString());
const target=resolve(process.argv[2]||'cloudflare-dashboard');
try{await lstat(target);throw Error('Output directory already exists')}catch(e){if(e.code!=='ENOENT')throw e}
for(const [name,data]of Object.entries(files)){if(isAbsolute(name)||name.split('/').includes('..'))throw Error('Unsafe path');const p=resolve(target,name);await mkdir(dirname(p),{recursive:true});await writeFile(p,data,{flag:'wx'})}
console.log('Extracted '+Object.keys(files).length+' source files');
